# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: the one way this repo runs a GraphQL query against an outside API: a POST through
# ds.util.http (same logging, secrets filtered), plus the GraphQL parts of the record:
# operation, variables, the query text, `errors`, rows / page info, chosen `extensions`.
# Usage: `result = await graphql.gql(url, query, variables, source="startgg", headers=h)`,
# then `result.data` / `result.errors`; turning errors into exceptions is the caller's job.
# ---------------------------------------------------------------------------
from __future__ import annotations

import re
from collections.abc import Callable, Mapping
from dataclasses import dataclass
from typing import TYPE_CHECKING, Any

from ds.util import http

if TYPE_CHECKING:
    import httpx2

__all__ = ["GraphQLResult", "gql", "operation_name"]

_OP_RE = re.compile(r"\b(?:query|mutation|subscription)\s+(\w+)")
_MAX_DEPTH = 4  # how deep to look for a paged connection in `data`


@dataclass
class GraphQLResult:
    """One GraphQL response: the HTTP status and the parsed body, as the API sent them"""

    status: int
    body: Any
    """The JSON body (a dict), or the start of the text when it wasn't JSON."""

    @property
    def data(self) -> dict[str, Any] | None:
        """The `data` object (None when the API sent none, eg on a refusal)."""
        return self.body.get("data") if isinstance(self.body, dict) else None

    @property
    def errors(self) -> list[str]:
        """The `errors` messages ([] when there are none)."""
        found = self.body.get("errors") if isinstance(self.body, dict) else None
        return [str(e.get("message", e)) if isinstance(e, dict) else str(e) for e in found or []]


def operation_name(query: str) -> str:
    """The operation's name in a GraphQL document, eg 'PlayerSets'; 'query' when unnamed."""
    found = _OP_RE.search(query)
    return found.group(1) if found else "query"


def _page(data: Any, depth: int = 0) -> dict[str, Any]:
    """`rows` and `page_info` of the first paged connection in `data`

    That is a dict with a `nodes` list, the usual GraphQL shape for a page; {} when none.
    """
    if not isinstance(data, dict) or depth > _MAX_DEPTH:
        return {}
    if isinstance(data.get("nodes"), list):
        return {"rows": len(data["nodes"]), "page_info": data.get("pageInfo")}
    for value in data.values():
        if found := _page(value, depth + 1):
            return found
    return {}


async def gql(  # one keyword per part of the request and its record
    url: str,
    query: str,
    variables: Mapping[str, Any] | None = None,
    *,
    source: str,
    headers: Mapping[str, str] | None = None,
    extensions: Mapping[str, str] | None = None,
    fields: Mapping[str, Any] | None = None,
    check: Callable[[GraphQLResult], None] | None = None,
    client: httpx2.AsyncClient | None = None,
) -> GraphQLResult:
    """POST one GraphQL query and return its status and body; logs one 'graphql' record

    Args:
        url: the API's endpoint.
        query: the GraphQL document. Kept in the record as is: a module-level constant (eg
            from a queries.py) is shared, not copied, so it costs the log nothing.
        variables: the query's variables.
        source: who is called, eg 'startgg'.
        headers: eg the auth header (filtered out of the record, see ds.util.http).
        extensions: response `extensions` keys to log, by field name, eg
            {'objects': 'queryComplexity'} for start.gg's cost of the request.
        fields: extra fields known up front, eg {'wait_ms': 12}.
        check: raises the API's own errors for a bad result (eg start.gg's typed errors);
            run inside the record, so what it raises is the record's `error`.
        client: an httpx2.AsyncClient to reuse across many calls (eg the pages of one lookup).
    """
    variables = dict(variables or {})
    op = operation_name(query)
    extra = {"op": op, "variables": variables, "query": query, **(fields or {})}
    async with http.arequest(
        "POST",
        url,
        source=source,
        name=op,
        kind="graphql",
        fields=extra,
        client=client,
        json={"query": query, "variables": variables},
        headers=dict(headers or {}),
    ) as (resp, call):
        # the body is already in the record's own fields (op, variables, query)
        call.pop("request_body", None)
        try:
            body = resp.json()
        except ValueError:
            body = resp.text[: http.MAX_ERROR_CHARS]
        result = GraphQLResult(resp.status_code, body)
        if result.errors:
            call["errors"] = result.errors
        if isinstance(body, dict):
            found = body.get("extensions") or {}
            call.update({name: found.get(key) for name, key in (extensions or {}).items()})
            # some APIs (start.gg) answer refusals as {"message": ...}; not `message`, which
            # is the log record's own
            if body.get("message"):
                call["api_message"] = body["message"]
        call.update(_page(result.data))
        if check is not None:
            check(result)
        return result
